    typeName: { L: "鉄筋コンクリート L型", T: "鉄筋コンクリート 逆T型", kenchi: "間知ブロック練積み" },
    drain: [3000, 5000, 8000],                 // 水抜き・裏込め砕石・透水マット（円/㎡）
    accessK: { ok: [1, 1, 1], small: [1.1, 1.2, 1.35], hand: [1.2, 1.4, 1.6] },
    accessName: { ok: "重機が入る", small: "小型の重機だけ", hand: "手作業" },
